import{_ as i,a}from"./chunks/Install45.BdJsAdnu.js";import{_ as o,o as r,c as t,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"Prerequisiti","description":"","frontmatter":{"source_hash":"a6ac1989f7","source_commit":"0bbdbd2"},"headers":[],"relativePath":"it/install/prerequisites.md","filePath":"it/install/prerequisites.md"}'),s={name:"it/install/prerequisites.md"};function n(p,e,c,d,m,u){return r(),t("div",null,[...e[0]||(e[0]=[l('<p>Ti serve uno smartphone Android.</p><p><img src="https://www.android.com/static/images/logos/andy-peace.png" alt="https://www.android.com/static/images/logos/andy-peace.png"></p><ul><li>La versione minima di Android supportata è la 8.0 (il supporto di Android 7 è stato ritirato con il rilascio del <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 luglio 2026</a>).</li><li>Se collegherai xDrip a un sensore, il tuo telefono deve supportare il Bluetooth Low Energy (BLE): per verificarlo puoi usare utility <a href="https://play.google.com/store/apps/details?id=com.treeteam.blechecker" target="_blank" rel="noreferrer">come questa</a>.</li><li>Se vuoi usare la funzione master - follower integrata in xDrip (chiamata xDrip Sync), su entrambi i telefoni devono essere installati i <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Google Play Services</a>.</li><li>Per usare la scansione NFC dei sensori Libre 1 e 2/2+ (solo UE), o per collegarti direttamente a un sensore Libre 2/2+ (UE), il tuo telefono deve avere un lettore NFC compatibile.</li><li>Se usi Android 16 o superiore, assicurati di usare una versione recente di xDrip (almeno l&#39;<a href="./download.html#latest-release">ultima release</a>, ne parleremo più avanti: continua a leggere).</li></ul><h3 id="google-play-services" tabindex="-1">Google Play Services <a class="header-anchor" href="#google-play-services" aria-label="Permalink to &quot;Google Play Services {#google-play-services}&quot;">​</a></h3><p>​ <img src="http://www.gstatic.com/android/market_images/web/favicon_v3.ico" alt="http://www.gstatic.com/android/market_images/web/favicon_v3.ico"></p><p>Se il tuo telefono non ha i Google Play Services (alcuni telefoni Huawei e cinesi non li hanno) puoi comunque usare xDrip, ma non la funzione xDrip Sync che, come detto sopra, si basa su di essi.<br> Con sistemi operativi alternativi basati su Android potresti incontrare problemi imprevisti.<br> In questo caso assicurati di <a href="./../use/sync.html#disable-sync">disattivare le funzioni di sincronizzazione</a>.</p><h3 id="family-link" tabindex="-1">Family Link <a class="header-anchor" href="#family-link" aria-label="Permalink to &quot;Family Link {#family-link}&quot;">​</a></h3><img src="https://families.google/intl/it_ALL/familylink/static/img/fl-icon.svg" style="zoom:25%;"><p>Per installare xDrip su un telefono controllato da <a href="https://families.google.com/families" target="_blank" rel="noreferrer">Google Family Link</a> <strong>devi disattivarlo</strong> finché non hai installato l&#39;app.<br> Se poi vuoi riattivarlo, assicurati che xDrip abbia tutte le autorizzazioni e nessun limite di tempo.</p><h3 id="work-profile" tabindex="-1">Profilo di lavoro <a class="header-anchor" href="#work-profile" aria-label="Permalink to &quot;Profilo di lavoro {#work-profile}&quot;">​</a></h3><img src="https://developer.android.com/static/images/work/cards/briefcase_600px.png" style="zoom:15%;"><p>Se usi un telefono gestito dall&#39;azienda, le policy aziendali potrebbero impedirti di installare xDrip.</p><p>Puoi provare a installare l&#39;app da un computer con <a href="./../troubleshoot/ADB.html#smartphone">Android Debug</a>, dopo aver attivato le opzioni sviluppatore sul telefono. Ricordati di eliminare xDrip dal profilo di lavoro se necessario, perché potrebbe essere installato in entrambi gli ambienti.</p><h3 id="phone-time-accuracy" tabindex="-1">Precisione dell&#39;ora del telefono <a class="header-anchor" href="#phone-time-accuracy" aria-label="Permalink to &quot;Precisione dell&#39;ora del telefono {#phone-time-accuracy}&quot;">​</a></h3><p>Sincronizza l&#39;orologio del telefono con la rete (Impostazioni Android -&gt; <a href="https://support.google.com/android/answer/2841106" target="_blank" rel="noreferrer">Data e ora</a>).<br> Assicurati di avere il fuso orario corretto e che l&#39;ora legale corrisponda.</p><img src="'+i+'" style="zoom:65%;"><h3 id="energy-savings" tabindex="-1">Risparmio energetico <a class="header-anchor" href="#energy-savings" aria-label="Permalink to &quot;Risparmio energetico {#energy-savings}&quot;">​</a></h3><p><strong><a href="./../troubleshoot/savings.html">Disattiva</a></strong> tutte le impostazioni Android di risparmio energetico/batteria del telefono prima di installare xDrip.<br> Puoi provare a ripristinarne alcune dopo aver verificato che xDrip funziona correttamente, ma <strong>non</strong> ottimizzare <strong>mai</strong> xDrip.</p><br><h3 id="play-protect" tabindex="-1">Play Protect <a class="header-anchor" href="#play-protect" aria-label="Permalink to &quot;Play Protect {#play-protect}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Di solito Google Play Protect non blocca xDrip, ma potrebbe bloccare <a href="./../use/OOP.html">OOP</a>.</p></div><p>Se xDrip smette di funzionare ogni notte tra mezzanotte e le 3, prova a disattivare Google Play Protect.<br> Poiché si tratta di un&#39;importante funzione di sicurezza del telefono, evita di usarlo per scaricare link sconosciuti e giochi: se decidi di disattivare Play Protect, mantieni il telefono del CGM il più sicuro possibile.</p><p>Trovi Google Play Protect nelle impostazioni dell&#39;app Play Store del telefono.</p><img src="'+a+'" style="zoom:75%;"><br><p><a href="./download.html">Passa al download di xDrip</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Ultima modifica 18/7/2026</em></a></p>',28)])])}const b=o(s,[["render",n]]);export{f as __pageData,b as default};
